using System.Collections.Generic;
using UnityEngine;
using System.Collections;
using System;

public class ActionSystem : MonoBehaviour
{
    public static ActionSystem Instance { get; private set; } //单例模式

    private List<GameAction> reactions = null;
    public bool IsPerforming { get; private set; } = false;
    private static Dictionary<Type, List<Action<GameAction>>> preSubs = new();      //存储不同动作类型所对应的执行前回调函数列表
    private static Dictionary<Type, List<Action<GameAction>>> postSubs = new();     //存储不同动作类型所对应的执行后回调函数列表
    private static Dictionary<Type, Func<GameAction, IEnumerator>> performers = new();  //存储不同动作类型所对应的执行回调函数列表

    public void Perform(GameAction action, System.Action OnPerformFinished = null)
    {
        if (IsPerforming)
        {
            Debug.Log("当前有多个Perform执行了");
            return;
        }
        Debug.Log("当前执行的是:"+ action.ToString());
        IsPerforming = true;
        StartCoroutine(Flow(action, () =>
        {
            IsPerforming = false;
            OnPerformFinished?.Invoke();
        }));
    }

    public void AddReaction(GameAction gameAction)
    {
        reactions?.Add(gameAction);
    }

    private IEnumerator Flow(GameAction action, Action OnFlowFinished = null)
    {
        reactions = action.PreReactions;
        PerformSubscribers(action, preSubs);
        yield return PerformReactions();

        reactions = action.PerformReactions;
        yield return PerformPerformer(action);
        yield return PerformReactions();

        reactions = action.PostReactions;
        PerformSubscribers(action, postSubs);
        yield return PerformReactions();

        OnFlowFinished?.Invoke();   
    }

    private IEnumerator PerformPerformer(GameAction action)
    {
        Type type = action.GetType();
        if(performers.ContainsKey(type))
        {
            yield return performers[type](action);
        }
    }
    private void PerformSubscribers(GameAction action, Dictionary<Type, List <Action<GameAction>>> subs)
    {
        Type type = action.GetType();
        if(subs.ContainsKey(type))
        {
            foreach (var sub in subs[type])
            {
                sub(action);
            }
        }
    }

    private IEnumerator PerformReactions()
    {
        foreach(var reaction in reactions) 
        {
            yield return Flow(reaction);
        }
    }


    //
    public static void AttachPerformer<T>(Func<T, IEnumerator> performer) where T : GameAction
    {
        Type type = typeof(T);
        IEnumerator wrappedPerformer(GameAction action) => performer((T)action);
        if (performers.ContainsKey(type)) performers[type] = wrappedPerformer;
        else performers.Add(type, wrappedPerformer);
    }

    //
    public static void DetachPerformer<T>() where T : GameAction
    {
        Type type = typeof(T);
        if(performers.ContainsKey(type)) performers.Remove(type);
    }

    //订阅其他动作反应，并根据预反应还是后反应，将它添加到对应订阅列表里的对应动作，传入的委托函数应该为添加反应的操作
    public static void SubscribeReaction<T>(Action<T> reaction, ReactionTiming timing) where T : GameAction
    {
        Dictionary<Type, List<Action<GameAction>>> subs = timing == ReactionTiming.PRE ? preSubs : postSubs;
        void wrappedReaction(GameAction action) => reaction((T)action);
        if (subs.ContainsKey(typeof(T)))
        {
            subs[typeof(T)].Add(wrappedReaction);
        }
        else
        {
            subs.Add(typeof(T), new());
            subs[typeof(T)].Add(wrappedReaction);
        }
    }

    public static void UnsubscribeReaction<T>(Action<T> reaction, ReactionTiming timing) where T : GameAction
    {
        Dictionary<Type, List<Action<GameAction>>> subs = timing == ReactionTiming.PRE ? preSubs : postSubs;
        if(subs.ContainsKey(typeof(T)))
        {
            void wrappedReaction(GameAction action) => reaction((T)action);
            subs[typeof(T)].Remove(wrappedReaction);
        }
    }



    public void Awake()
    {
        if(Instance != null && Instance != this)
        {
            Destroy(Instance);
        }
        else
        {
            Instance = this;
        }
    }
}

using NUnit.Framework;
using UnityEngine;
using System.Collections.Generic;

//抽象类,三个列表存储动作发生前，动作发生后，动作执行中的动作

public abstract class GameAction
{
    //这些列表允许动作在执行前、执行过程中、执行后插入其他子动作，形成动作链。
    public List<GameAction> PreReactions { get; private set; } = new();
    public List<GameAction> PerformReactions { get; private set; } = new();
    public List<GameAction> PostReactions { get; private set; } = new();

}

using System.Collections.Generic;
using UnityEngine;

//卡牌模型
public class Card 
{
    public string Description => CardData.Description;
    public CardType CardType => CardData.CardType;
    public CardRarityType CardRarityType => CardData.CardrarityType;
    public Sprite Image => CardData.Image;
    public Effect ManualTargetEffect => CardData.ManualTargetEffect;
    public List<AutoTargetEffect> OtherEffects => CardData.OtherEffects;

    public bool CanBeUpgradeInfinitely => CardData.CanBeUpgradeInfinitely;

    public string Title { get; private set; }
    public int BaseDamage {  get;private set; }
    public int BaseBlock { get; private set; }
    public int BaseMagic { get; private set; }

    public int Mana {  get; private set; }

    //卡牌是否升级,默认没升级
    public bool Upgraded {  get; private set; }=false;


    public  CardDataSO CardData {  get; private set; }
     public Card(CardDataSO cardDataSO)
    {
        CardData = cardDataSO;
        Mana = cardDataSO.Mana;
        BaseDamage = cardDataSO.baseDamage;
        BaseBlock = cardDataSO.baseBlock;
        BaseMagic = cardDataSO.baseMagic;
        Title = CardData.name;
    }

    public Card Clone()
    {
        Card clone = new Card(this.CardData);
        clone.Mana = this.Mana;
        clone.BaseDamage = this.BaseDamage;
        clone.BaseBlock = this.BaseBlock;
        clone.BaseMagic = this.BaseMagic;
        clone.Title = this.Title;
        Debug.Log("原来的卡牌描述文本为：" + Description);

        return clone;
    }
    //设置为升级过了
    public  void Upgrade()
    {
        //当已经升级过且不能连续升级时，直接返回，否则继续升级
        if(Upgraded && !CanBeUpgradeInfinitely) return;
        Upgraded = true;
        BaseDamage += CardData.upgradeDamage;
        BaseBlock += CardData.upgradeBlock;
        BaseMagic += CardData.upgradeMagic;
        Mana += CardData.upgradeMana;
        Title += CardData.upgradeName;

    }


}

