using DG.Tweening;
using NUnit.Framework;
using System.Collections;
using System.Collections.Generic;
using Unity.VisualScripting;
using UnityEngine;

public class CardSystem : MonoBehaviour
{
    [field : SerializeField] public HandView handView { get; private set; } //引用手牌
    [SerializeField] private Transform drawPilePoint; //引用手牌
    [SerializeField] private Transform discardPilePoint; //引用手牌


    //三个列表分别存放抽牌堆，手牌堆，弃牌堆的实例数据
    private readonly List<Card> drawPile = new();
    private readonly List<Card> discardPile = new();
    private readonly List<Card> handPile  = new();

    //单例
    public static CardSystem Instance {  get; private set; }

    private void Awake()
    {
        if(Instance != null && Instance != this)
        {
            Destroy(Instance );
        }else
        {
            Instance = this;
        }
    }

    private void OnEnable()
    {
        //添加动作的执行者函数
        ActionSystem.AttachPerformer<DrawCardsGA>(DrawCardsPerformer);
        ActionSystem.AttachPerformer<DiscardAllCardsGA>(DiscordAllCardsPerformer);
        ActionSystem.AttachPerformer<PlayCardGA>(PlayCardPerformer);

        //添加订阅反应的函数
        ActionSystem.SubscribeReaction<EnemyTurnGA>(EnemyTurnPreReaction, ReactionTiming.PRE);
        ActionSystem.SubscribeReaction<EnemyTurnGA>(EnemyTurnPostReaction, ReactionTiming.POST);

    }
    private void OnDisable()
    {
        ActionSystem.DetachPerformer<DrawCardsGA>();
        ActionSystem.DetachPerformer<DiscardAllCardsGA>();
        ActionSystem.DetachPerformer<PlayCardGA>();

        ActionSystem.UnsubscribeReaction<EnemyTurnGA>(EnemyTurnPreReaction, ReactionTiming.PRE);
        ActionSystem.UnsubscribeReaction<EnemyTurnGA>(EnemyTurnPostReaction, ReactionTiming.POST);
    }

    //设置抽牌堆,也就是实例化卡牌数据
    public void SetUp(List<CardDataSO> deckData)
    {
        foreach(var  cardDataSO in deckData)
        {
            Card card = new(cardDataSO);
            drawPile.Add(card);
        }
    }

    //将Card的克隆复制到抽牌堆里
    public void SetUpClonedCard(List<Card> deckData)
    {
        foreach (var card in deckData)
        {
            Card card1 = card.Clone();
            drawPile.Add(card1);
        }
        Debug.Log("场景内的卡牌数据已经加载完全");
    }

    public void ReMoveAllPile()
    {
        DiscardAllCardsGA discardAllCardsGA = new();
        ActionSystem.Instance.Perform(discardAllCardsGA);
        drawPile.Clear();
        discardPile.Clear();
    }
    /// <summary>
    /// 将弃牌作为链反应执行
    /// </summary>
    public void ReMoveAllPileAddReaction()
    {
        DiscardAllCardsGA discardAllCardsGA = new();
        ActionSystem.Instance.AddReaction(discardAllCardsGA);
        drawPile.Clear();
        discardPile.Clear();
    }

    //performer
    //抽牌执行者函数
    private IEnumerator DrawCardsPerformer(DrawCardsGA drawCardGA)
    {
        int actualAmount = Mathf.Min(drawCardGA.Amount, drawPile.Count);
        int notDrawnAmount = drawCardGA.Amount - actualAmount;
        for(int  i = 0; i < actualAmount; i++)
        {
            yield return DrawCard();
        }
        if(notDrawnAmount > 0)
        {
            if(discardPile.Count <= 0)
            {
                Debug.Log("无法抽牌，抽牌堆和弃牌堆均为0");
                yield break;
            }
            //洗牌重抽
            RefillDeck();
            for(int i = 0;i < notDrawnAmount;i++)
            {
                yield return DrawCard();
            }
        }
    }
    //丢弃掉所有手牌执行者函数
    private IEnumerator DiscordAllCardsPerformer(DiscardAllCardsGA discardAllCardsGA)
    {
        List<Card> cardsToDiscard = new(handPile);
        handPile.Clear();

        foreach(Card card in cardsToDiscard)
        {
            CardView cardView = handView.RemoveCard(card);
            yield return DiscordCard(cardView);
        }
    }
    //打出卡牌执行者函数
    private IEnumerator PlayCardPerformer(PlayCardGA playCardGA)
    {
        handPile.Remove(playCardGA.Card);
        //discardPile.Add(playCardGA.Card);这个应该在弃牌动作完成
        CardView cardView = handView.RemoveCard(playCardGA.Card);
        yield return DiscordCard(cardView);


        SpendManaGA spendManaGA = new(playCardGA.Card.Mana);
        ActionSystem.Instance.AddReaction(spendManaGA);

        if(playCardGA.Card.ManualTargetEffect != null)
        {
            PerformEffectGA performEffectGA = new(playCardGA.Card.ManualTargetEffect, new() { playCardGA.Manualtarget }, playCardGA.Card);
            ActionSystem.Instance.AddReaction(performEffectGA); 
        }
        foreach(var effectWrapper in playCardGA.Card.OtherEffects)
        {
            List<CombatantView> targets = effectWrapper.TargetMode.GetTargets();
            //为每个效果创建执行效果的游戏动作
            PerformEffectGA performEffectGA = new(effectWrapper.Effect, targets, playCardGA.Card);
            //打牌动作执行中的连锁反应，实现效果
            ActionSystem.Instance.AddReaction(performEffectGA);
        }
    }

    //Reactions反应
    //敌人回合前预反应,丢弃所有手牌
    private void EnemyTurnPreReaction(EnemyTurnGA enemyTurnGA)
    {
        DiscardAllCardsGA discardAllCardsGA = new();
        ActionSystem.Instance.AddReaction(discardAllCardsGA);
    }
    //敌人执行回合结束后的反应，为回合抽牌
    private void EnemyTurnPostReaction(EnemyTurnGA deemyTurnGA)
    {
        DrawCardsGA drawCardsGA = new(5);
        ActionSystem.Instance.AddReaction(drawCardsGA);
    }

    //Helpers
    //抽牌函数
    private IEnumerator DrawCard()
    {
        Card card = drawPile.Draw();
        if (card == null) yield break;
        handPile.Add(card);
        CardView cardView = CardViewCreator.Instance.CreateCardView(card, drawPilePoint.position, drawPilePoint.rotation);
        yield return handView.AddCard(cardView);
    }
    //将所有弃牌堆的牌并入抽牌堆
    private void RefillDeck()
    {
        drawPile.AddRange(discardPile);
        discardPile.Clear();
    }

    //丢弃目标牌
    private IEnumerator DiscordCard(CardView cardView)
    {
        cardView.transform.DOScale(Vector3.zero, 0.15f);
        Tween tween = cardView.transform.DOMove(discardPilePoint.position, 0.15f);
        yield return tween.WaitForCompletion();
        //动画完成后才将牌加入弃牌堆
        discardPile.Add(cardView.Card);
        Destroy(cardView.gameObject);
    }

    /// <summary>
    ///随机生成卡牌数据实例
    ///普通：65%
    ///罕见：25%
    ///稀有：10%
    ///当前默认生成战士牌组
    /// </summary>
    public Card GenerateCard()
    {
        CardPoolDataSO cardPool = AllDataSystem.Instance.IroncladCardPool;
        int rand = Random.Range(0, 100);
        CardDataSO cardDataSO;
        if(rand < 65)
            cardDataSO = cardPool.CommonCardPool[Random.Range(0, cardPool.CommonCardPool.Count)];
        else if(rand < 90)
            cardDataSO = cardPool.UncommonCardPool[Random.Range(0, cardPool.UncommonCardPool.Count)];
        else cardDataSO = cardPool.RareCardPool[Random.Range(0, cardPool.RareCardPool.Count)];
        Card card = new(cardDataSO);
        return card;
    }

    //根据卡牌类型获得中文版文字
    public static string GetChinceseTypeText(CardType cardType)
    {
        switch (cardType)
        {
            case CardType.Attack:
                return "攻击";
            case CardType.Skill:
                return "技能";
            case CardType.Power:
                return "能力";
            default:
                break;
        }
        return "";
    }
}

using DG.Tweening;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class EnemySystem : MonoBehaviour
{
    //引用
    [SerializeField] private EnemyBoardView enemyBoardView;                           //引用敌人棋盘视图

    public List<EnemyView> enemyViews => enemyBoardView.EnemyViews;                   //返回

    //单例
    public static EnemySystem Instance;

    private void Awake()
    {
        if(Instance != null && Instance != this)
        {
            Destroy(Instance);
        }
        else
        {
            Instance = this;
        }
    }
    private void OnEnable()
    {
        ActionSystem.AttachPerformer<EnemyTurnGA>(EnemyTurnPerformer);
        ActionSystem.AttachPerformer<AttackHeroGA>(AttackHeroPerformer);
        ActionSystem.AttachPerformer<KillEnemyGA>(KillEnemyPerformer);

        //添加订阅反应的函数
        ActionSystem.SubscribeReaction<EnemyTurnGA>(EnemyTurnPreReaction, ReactionTiming.PRE);
        ActionSystem.SubscribeReaction<EnemyTurnGA>(EnemyTurnPostReaction, ReactionTiming.POST);
    }
    private void OnDisable()
    {
        ActionSystem.DetachPerformer<EnemyTurnGA>();
        ActionSystem.DetachPerformer<AttackHeroGA>();
        ActionSystem.DetachPerformer<KillEnemyGA>();

        ActionSystem.UnsubscribeReaction<EnemyTurnGA>(EnemyTurnPreReaction, ReactionTiming.PRE);
        ActionSystem.UnsubscribeReaction<EnemyTurnGA>(EnemyTurnPostReaction, ReactionTiming.POST);
    }

    //初始化敌人系统，创建多个敌人视图
    public void Setup(List<EnemyDataSO> enemyDataSOs)
    {
        Debug.Log("开始加载敌人列表");
        foreach(var enemyDataSO in enemyDataSOs)
        {
            Debug.Log("加载敌人"+ enemyDataSO.id);
            enemyBoardView.AddEnemy(enemyDataSO);
        }
        Debug.Log("敌人数据已经加载完全");
    }
    //销毁所有敌人
    public void RemoveAllEnemyView()
    {
        //StartCoroutine(enemyBoardView.RemoveAllEnemyView());
        for (int i = enemyBoardView.EnemyViews.Count - 1; i >= 0; i--)
        {
            KillEnemyGA killEnemyGA = new KillEnemyGA(enemyViews[i]);
            Debug.Log("杀死敌人:" + killEnemyGA.TargetEnemyView.myEnemyDataSO.id);
            ActionSystem.Instance.Perform(killEnemyGA);
        }
        Debug.Log("当前场景敌人数量:"+enemyBoardView.EnemyViews.Count);
    }
    //等待特定时间
    public void WaitTime(float duration)
    {
        float x=0;
        while(x < duration)
        {
            x += Time.deltaTime;
        }
    }

    //敌人回合开始前显示敌人回合
    private void EnemyTurnPreReaction(EnemyTurnGA enemyTurnGA)
    {
        CombatFeedbackSystem.Instance.ShowTurnText("敌人回合");
    }
    //敌人执行回合结束后的反应，为显示玩家回合
    private void EnemyTurnPostReaction(EnemyTurnGA deemyTurnGA)
    {
        CombatFeedbackSystem.Instance.ShowTurnText("玩家回合");
    }

    private IEnumerator EnemyTurnPerformer(EnemyTurnGA enemyTurnGA)
    {
        Debug.Log("进入敌人回合");
        //CombatFeedbackSystem.Instance.ShowTurnText("敌人回合");
        yield return new WaitForSeconds(1f);


        //遍历所有敌人，并添加相应攻击英雄反应
        foreach (var enemyView in enemyBoardView.EnemyViews)
        {
            AttackHeroGA attackHeroGA = new(enemyView);
            ActionSystem.Instance.AddReaction(attackHeroGA);
        }
        yield return null;
    }

    //攻击英雄动作执行者函数
    private IEnumerator AttackHeroPerformer(AttackHeroGA attackHeroGA)
    {
        EnemyView attacker = attackHeroGA.Attacker;
        //攻击效果（动画）
        Tween tween = attacker.transform.DOMoveX(attacker.transform.position.x - 1f, 0.25f);
        yield return tween.WaitForCompletion();
        attacker.transform.DOMoveX(attacker.transform.position.x + 1f, 0.25f);
        //造成伤害(添加造成伤害动作进反应里，反应列表会执行这个造成伤害动作)
        List<DamageInfo> damageInfoList = new List<DamageInfo>() 
            { new DamageInfo(attacker, HeroSystem.Instance.HeroView, attacker.AttckPower) };
        DealDamageGA dealDamageGA = new(damageInfoList);
        //DealDamageGA dealDamageGA = new(attacker.AttckPower, new() { HeroSystem.Instance.HeroView },attackHeroGA.Caster);
        ActionSystem.Instance.AddReaction(dealDamageGA);


    }

    //杀死敌人动作执行这函数
    public IEnumerator KillEnemyPerformer(KillEnemyGA killEnemyGA)
    {
        yield return enemyBoardView.RemoveEnemyView(killEnemyGA.TargetEnemyView);

        //每次杀死敌人都判断以下敌人棋盘是否为空,为空就加载奖励界面,
        if(enemyBoardView.EnemyViews.Count == 0)
        {
            AwardSystem.Instance.AwardShow();
            CardSystem.Instance.ReMoveAllPileAddReaction();
        }

    }

}

using DG.Tweening;
using System.Collections;
using System.Collections.Generic;

using TMPro;
using Unity.VisualScripting;
using UnityEngine;

//管理伤害
public class DamageSystem : MonoBehaviour
{
    //引用
    [SerializeField] private GameObject damageVFX;                    //伤害特效
    [SerializeField] private TMP_Text damageTextVFX;                //伤害文本特效


    //函数
    //unity运行函数
    private void OnEnable()
    {
        ActionSystem.AttachPerformer<DealDamageGA>(DealDamagePerformer);
    }
    private void OnDisable()
    {
        ActionSystem.DetachPerformer<DealDamageGA>();
    }


    //执行者函数
    public IEnumerator DealDamagePerformer(DealDamageGA dealDamageGA)
    {
        //遍历攻击目标列表，造成生命值减少和生成伤害特效
        foreach(var damageInfo in dealDamageGA.damageInfoList)
        {
            if(damageInfo.target == null)      //假如积累过多对同一目标的伤害动作（作为某个动作的链式动作时有可能），
                                    //会造成目标死亡后仍访问原目标进行伤害动作，而目标死亡会销毁
                                    //为防止访问空对象，需判断目标是否为空
            {
                yield break;
            }

            //生成伤害文本动画
            //Vector3 vector3 = damageInfo.target.transform.clickPosition;
            //TMP_Text dmgTextVFX = Instantiate(TextVFX, vector3- Vector3.up, Quaternion.identity);
            //dmgTextVFX.text = damageInfo.currentDamage.ToString();
            //Tween tween =  dmgTextVFX.gameObject.transform.DOMove(vector3 + Vector3.up, 0.5f);
            //yield return tween;
            //Tween tween1 = dmgTextVFX.gameObject.transform.DOMove(vector3 - Vector3.up, 0.5f);
            //yield return tween1;
            // 生成伤害文本动画
            //StartCoroutine(ShowDamage(damageInfo));
            CombatFeedbackSystem.Instance.ShowDamageText(damageInfo);

            damageInfo.target.Damage(damageInfo.currentDamage);
            //GameObject vfx = Instantiate(damageVFX, damageInfo.target.transform.clickPosition, Quaternion.identity);
            CombatFeedbackSystem.Instance.ShowDamageVFX(damageInfo);
            yield return new WaitForSeconds(0.15f);

            //判断目标血量是否为0
            if(damageInfo.target.CurrentHealth <= 0)
            {
                if(damageInfo.target is EnemyView)
                {
                    //如果敌人血量为0，执行杀死敌人动作
                    KillEnemyGA killEnemyGA = new((EnemyView)damageInfo.target);
                    ActionSystem.Instance.AddReaction(killEnemyGA);
                }
                else
                {
                    //玩家血量为0，执行结束逻辑
                }
            }
        }
    }

    //专门的伤害计算器
    public static int CalculateDamage(DamageInfo info)
    {
        // 攻击者Buff
        foreach (var buff in info.attacker.buffs)
        {
            buff.ModifyDamageGive(info);
        }
        if(info.target != null)
        {
            // 目标Buff
            foreach (var buff in info.target.buffs)
            {
                buff.ModifyDamageTaken(info);
            }
        }


        Debug.Log("当前伤害为：" + info.currentDamage);

        return Mathf.Max(0, info.currentDamage);
    }

    //伤害文本特效
    public IEnumerator ShowDamage(DamageInfo damageInfo)
    {

        Vector3 pos = damageInfo.target.transform.position;

        // 随机一点偏移，避免数字重叠
        Vector3 randomOffset = new Vector3(
            Random.Range(-0.3f, 0.3f),
            Random.Range(-0.1f, 0.1f),
            0
        );

        TMP_Text dmgText = Instantiate(
            damageTextVFX,
            pos + randomOffset,
            Quaternion.identity
        );

        dmgText.text = damageInfo.currentDamage.ToString();

        Transform tf = dmgText.transform;

        // 初始状态
        Vector3 startScale = tf.localScale;
        tf.localScale = Vector3.zero;

        Color color = dmgText.color;
        color.a = 1f;
        dmgText.color = color;

        // 目标位置
        Vector3 targetPos = tf.position + Vector3.up * 2f;

        // Sequence
        DG.Tweening.Sequence seq = DOTween.Sequence();

        // 1. 出现爆开
        seq.Append(
            tf.DOScale(startScale *1.3f, 0.12f)
                .SetEase(Ease.OutBack)
        );

        // 2. 回弹到正常大小
        seq.Append(
            tf.DOScale(startScale *1f, 0.08f)
        );

        // 3. 上浮（和后续并行）
        seq.Join(
            tf.DOMove(targetPos, 0.8f)
                .SetEase(Ease.OutQuad)
        );

        // 4. 淡出
        seq.Join(
            dmgText.DOFade(0f, 0.8f).SetEase(Ease.InQuad)
        );

        // 5. 微旋转（可选）
        seq.Join(
            tf.DORotate(
                new Vector3(0, 0, Random.Range(-10f, 10f)),
                0.2f
            )
        );

        // 自动销毁
        seq.OnComplete(() =>
        {
            Destroy(dmgText.gameObject);
        });
        yield return seq.WaitForCompletion();
    }

    IEnumerator HitStop(float duration)
    {
        Time.timeScale = 0f;

        yield return new WaitForSecondsRealtime(duration);

        Time.timeScale = 1f;
    }
}

