[Serializable]
public abstract class BuffBase
{
    public string BuffId;
    public string BuffName;
    public Sprite Icon;

    // 层数
    public int Amount;

    // 持有者
    protected CombatantView owner;


    public abstract BuffBase DeepClone();
    public CombatantView GetOwner()
    {
        if(owner == null) return null;
        return owner;
    }
    public virtual void OnApply(CombatantView target)
    {
        owner = target;
        if(Icon != null)
        {
            CombatFeedbackSystem.Instance.ShowBuffSpriteVFX(target, Icon);
        }
        if(BuffName != null)
        {
            CombatFeedbackSystem.Instance.ShowBuffText(this.GetOwner(), this.BuffName);
        }
    }

    public virtual void OnRemove()
    {
        Amount = 0;
    }

    // 回合开始
    public virtual void AtTurnStart()
    {

    }

    // 回合结束
    public virtual void AtTurnEnd()
    {
        Amount--;

        if (Amount <= 0)
            owner.RemoveBuff(this);
        else
            owner.RefreshBuffUI(this);
    }

    // 打出卡牌
    public virtual void OnPlayCard(Card card)
    {

    }

    // 受到伤害前
