    /// </summary>
    private void SetMapState(bool active)
    {
        if (mapUIPanel != null)
        {
            mapUIPanel.SetActive(active);

            // 可选体验优化：每次打开地图时，让滚动条自动回到底部
            if (active && mapContent != null)
            {
                mapContent.anchoredPosition = new Vector2(mapContent.anchoredPosition.x, 0);
            }
        }
