    //    // 3. 动态调整 ScrollView Content 的高度，确保能滚到最上面
    //    // 高度 = (层数 - 1) * Y轴间距 + 顶部留白
    //    float requiredHeight = (mapGenerator.mapHeight - 1) * mapUIManager.nodeSpacingY + rightPadding;
